Link: https://lore.kernel.org/linux-mtd/1630998357-1359-1-git-send-email-mdalam@codeaurora.org

Here is the root cause:
The bug was caused by the incorrect handling of code word values in the `qcom_nandc_read_cw_raw()` function when using the QPIC V2 NAND controller. Specifically, the function was using the original code word index (`cw`) instead of the adjusted value (`raw_cw`), which accounts for the new register structure introduced in QPIC V2. This led to the controller misinterpreting the number of code words being read, resulting in potential data retrieval errors.

Here is the patch:
 /* performs raw read for one codeword */
 static int
 qcom_nandc_read_cw_raw(struct mtd_info *mtd, struct nand_chip *chip,
 		       u8 *data_buf, u8 *oob_buf, int page, int cw)
 {
 	struct qcom_nand_host *host = to_qcom_nand_host(chip);
 	struct qcom_nand_controller *nandc = get_qcom_nand_controller(chip);
 	struct nand_ecc_ctrl *ecc = &chip->ecc;
 	int data_size1, data_size2, oob_size1, oob_size2;
 	int ret, reg_off = FLASH_BUF_ACC, read_loc = 0;
+	int raw_cw = cw;

 	nand_read_page_op(chip, page, 0, NULL, 0);
 	host->use_ecc = false;

+	if (nandc->props->qpic_v2)
+		raw_cw = ecc->steps - 1;
+
 	clear_bam_transaction(nandc);
 	set_address(host, host->cw_size * cw, page);
-	update_rw_regs(host, 1, true, cw);
+	update_rw_regs(host, 1, true, raw_cw);
 	config_nand_page_read(chip);

 	data_size1 = mtd->writesize - host->cw_size * (ecc->steps - 1);
 	oob_size1 = host->bbm_size;

 	if (qcom_nandc_is_last_cw(ecc, cw)) {
 		data_size2 = ecc->size - data_size1 -
 			     ((ecc->steps - 1) * 4);
 		oob_size2 = (ecc->steps * 4) + host->ecc_bytes_hw +
 			    host->spare_bytes;
 	} else {
 		data_size2 = host->cw_data - data_size1;
 		oob_size2 = host->ecc_bytes_hw + host->spare_bytes;
 	}

 	if (nandc->props->is_bam) {
 		nandc_set_read_loc(chip, cw, 0, read_loc, data_size1, 0);
 		read_loc += data_size1;

 		nandc_set_read_loc(chip, cw, 1, read_loc, oob_size1, 0);
 		read_loc += oob_size1;

 		nandc_set_read_loc(chip, cw, 2, read_loc, data_size2, 0);
 		read_loc += data_size2;

 		nandc_set_read_loc(chip, cw, 3, read_loc, oob_size2, 1);
 	}

-	config_nand_cw_read(chip, false, cw);
+	config_nand_cw_read(chip, false, raw_cw);

 	read_data_dma(nandc, reg_off, data_buf, data_size1, 0);
 	reg_off += data_size1;

 	read_data_dma(nandc, reg_off, oob_buf, oob_size1, 0);
 	reg_off += oob_size1;

 	read_data_dma(nandc, reg_off, data_buf + data_size1, data_size2, 0);
 	reg_off += data_size2;

 	read_data_dma(nandc, reg_off, oob_buf + oob_size1, oob_size2, 0);

 	ret = submit_descs(nandc);
 	free_descs(nandc);
 	if (ret) {
 		dev_err(nandc->dev, "failure to read raw cw %d\n", cw);
 		return ret;
 	}

 	return check_flash_errors(host, 1);
 }



